import numpy as np
def grid(fixed, ax, rng=np.linspace(-3,3,13)):
    out=[]
    for a in rng:
        row=""
        for b in rng:
            x=np.array(fixed,dtype=float); x[ax[0]]=a; x[ax[1]]=b
            row+=str(int(run(x[None]).argmax(1)[0]))
        out.append(row)
    return out
